<script lang="ts">
  import { onMount, tick, untrack } from 'svelte';
  import Icon from './Icon.svelte';
  import GenericExpression from './GenericExpression.svelte';
  import GenericSceneNode from './GenericSceneNode.svelte';
  import CompiledArtifactInspector from './CompiledArtifactInspector.svelte';
  import CompiledWidget from '../../packages/companion-ui/src/CompiledWidget.svelte';
  import { compileWidget } from '../../packages/widget-compiler/src/index.ts';
  import type { WidgetSource, VisualNode, WidgetParameter, VisualValue, WidgetPort } from '../../packages/widget-compiler/src/types.ts';
  import { BROWSER_WIDGET_CAPABILITIES, type CompiledWidgetBundle } from '../../packages/widget-runtime/src/artifact.ts';
  import { createBehaviorState, evaluateExpression, type Expression, type Scalar, type BehaviorAction, type BehaviorSignal, type BehaviorState, type BehaviorFeedback } from '../../packages/widget-runtime/src/behavior.ts';
  import { createSourceHistory, editSource, undoSource, redoSource, sourceIdentity, CompilationFence, type SourceHistory } from './generic-widget-editor.ts';
  let { source, onsave, oncancel }: { source: WidgetSource; onsave: (source: WidgetSource, bundle: CompiledWidgetBundle) => Promise<void>; oncancel: () => void } = $props();
  let history = $state.raw(untrack(() => createSourceHistory(source)));
  const draft = $derived(history.present);
  const tabs = ['Design','Data','Behavior','Motion','Sound','Try'] as const;
  let tab = $state<typeof tabs[number]>('Design'), selected = $state(untrack(()=>source.scene[0]?.id ?? ''));
  let newKind = $state<VisualNode['kind']>('rectangle'), parentId = $state('');
  let error = $state(''), busy = $state(false), saving = $state(false), progress = $state('');
  let compiled = $state.raw<CompiledWidgetBundle>();
  let motion = $state(true), audioEnabled = $state(true), muted = $state(false);
  let targetWidth = $state(untrack(()=>source.size.width)), targetHeight = $state(untrack(()=>source.size.height));
  let dialog: HTMLDialogElement; let stage = $state<SVGSVGElement>();
  let tryPlayer = $state<{ dispatch: (event: string, updates?: Record<string,Scalar>, feedback?: Record<string,BehaviorFeedback>)=>void; reset:()=>void; enableAudio:()=>Promise<void> }>();
  let tryState = $state.raw<BehaviorState>(), outputs = $state.raw<Record<string,Scalar>>({});
  let inputValues = $state.raw<Record<string,Scalar>>({}), feedbackValues = $state.raw<Record<string,Scalar>>({}), qualities = $state.raw<Record<string,string>>({});
  let designOverrides = $state.raw<Record<string,Scalar>>({}), designRegions = $state.raw<Record<string,string>>({});
  let selectedEvent = $state(untrack(()=>source.behavior.events[0]?.id ?? ''));
  const fence = new CompilationFence<CompiledWidgetBundle>();
  let build = 0;
  const layerList = $derived(flatten(draft.scene));
  const layer = $derived(layerList.find(entry=>entry.node.id===selected)?.node);
  const references = $derived([...draft.parameters.map(p=>p.id),...draft.behavior.signals.map(s=>s.id)]);
  const regionIds = $derived(draft.behavior.regions.map(region=>region.id));
  const parameterValues = $derived(Object.fromEntries(draft.parameters.map(parameter=>[parameter.id,parameter.default])));
  const designState = $derived.by(()=>{try{return createBehaviorState(draft.behavior);}catch{return {values:Object.fromEntries(draft.behavior.signals.map(s=>[s.id,s.initial])),regions:Object.fromEntries(draft.behavior.regions.map(r=>[r.id,r.initial]))};}});
  const designValues = $derived({...parameterValues,...designState.values,...designOverrides});
  const previewRegions = $derived({...designState.regions,...designRegions});
  let selection = $state<{ bounds: { x:number;y:number;width:number;height:number }; transform:string }>();
  const selectedBounds = $derived(selection?.bounds);
  let drag: { pointer:number;x:number;y:number;toLocal:DOMMatrix;original:{x:number;y:number;width:number;height:number};resize:boolean;history:SourceHistory<WidgetSource> } | undefined;
  const compileIdentity = () => sourceIdentity({source:history.present,width:targetWidth,height:targetHeight,motion,audio:audioEnabled});
  function flatten(nodes:VisualNode[],depth=0):{node:VisualNode;depth:number}[]{return nodes.flatMap(node=>[{node,depth},...(node.kind==='group'?flatten(node.children,depth+1):[])]);}
  function listFor(nodes:VisualNode[],id:string):VisualNode[]|undefined {if(nodes.some(node=>node.id===id))return nodes;for(const node of nodes)if(node.kind==='group'){const found=listFor(node.children,id);if(found)return found;}return undefined;}
  function id(prefix:string){return `${prefix}-${crypto.randomUUID().slice(0,8)}`;}
  function invalidate(){fence.invalidate();compiled=undefined;tryState=undefined;outputs={};build++;busy=false;progress='';}
  function mutate(change:(source:WidgetSource)=>void){if(saving)return;const next=structuredClone(history.present);change(next);history=editSource(history,next);invalidate();error='';}
  function patchNode(patch:Record<string,unknown>){mutate(next=>{const node=flatten(next.scene).find(entry=>entry.node.id===selected)?.node;if(node)Object.assign(node,patch);});}
  function nodeValue(field:string):unknown{return (layer as unknown as Record<string,unknown>|undefined)?.[field];}
  function expr(value:unknown):Expression{return value&&typeof value==='object'?value as Expression:{literal:typeof value==='string'||typeof value==='number'||typeof value==='boolean'?value:0};}
  function isExpression(value:unknown){return !!value&&typeof value==='object';}
  function numeric(value:unknown,fallback=0){try{const result=isExpression(value)?evaluateExpression(value as Expression,{values:designValues,regions:previewRegions}):value;return typeof result==='number'&&Number.isFinite(result)?result:fallback;}catch{return fallback;}}
  function renderedLayer(svg:SVGSVGElement,nodeId:string){return [...svg.querySelectorAll<SVGGElement>('[data-source-layer-id]')].find(element=>element.dataset.sourceLayerId===nodeId);}
  $effect(()=>{
    const svg=stage,node=layer,design=tab==='Design';
    draft;designValues;previewRegions;
    if(!svg||!node||!design){selection=undefined;return;}
    let active=true;
    const measure=()=>{
      if(!active)return;
      try{
        const element=renderedLayer(svg,node.id),screen=svg.getScreenCTM(),nodeScreen=element?.getScreenCTM();
        if(!element||!screen||!nodeScreen){selection=undefined;return;}
        const box=element.getBBox(),matrix=screen.inverse().multiply(nodeScreen);
        if(![box.x,box.y,box.width,box.height,matrix.a,matrix.b,matrix.c,matrix.d,matrix.e,matrix.f].every(Number.isFinite)||(!box.width&&!box.height)){selection=undefined;return;}
        selection={bounds:{x:box.x,y:box.y,width:box.width,height:box.height},transform:`matrix(${matrix.a} ${matrix.b} ${matrix.c} ${matrix.d} ${matrix.e} ${matrix.f})`};
      }catch{selection=undefined;}
    };
    void tick().then(measure);
    void document.fonts.ready.then(measure);
    document.fonts.addEventListener('loadingdone',measure);
    return()=>{active=false;document.fonts.removeEventListener('loadingdone',measure);};
  });
  function addLayer(){const key=id('layer'),base={id:key,label:newKind,fill:'#72d8ca',stroke:'#b4e1e0',strokeWidth:0};let node:VisualNode;
    if(newKind==='group')node={...base,kind:'group',children:[]};
    else if(newKind==='text')node={...base,kind:'text',x:20,y:40,text:'Label',font:'sans',fontSize:24};
    else if(newKind==='line')node={...base,kind:'line',x:20,y:20,x2:100,y2:60,strokeWidth:2};
    else if(newKind==='path')node={...base,kind:'path',d:'M20 20 L100 20 L60 80 Z'};
    else if(newKind==='image')node={...base,kind:'image',x:20,y:20,width:80,height:60,assetId:draft.assets?.find(asset=>asset.mime.startsWith('image/'))?.id??''};
    else node={...base,kind:newKind,x:20,y:20,width:80,height:60,...(newKind==='rectangle'?{radius:8}:{})};
    mutate(next=>{const parent=flatten(next.scene).find(entry=>entry.node.id===parentId)?.node;if(parent?.kind==='group')parent.children.push(node);else next.scene.push(node);});selected=key;
  }
  function removeLayer(){mutate(next=>{const list=listFor(next.scene,selected);if(list)list.splice(list.findIndex(node=>node.id===selected),1);});selected=layerList[0]?.node.id??'';}
  function reorderLayer(delta:number){mutate(next=>{const list=listFor(next.scene,selected);if(!list)return;const i=list.findIndex(node=>node.id===selected),j=Math.max(0,Math.min(list.length-1,i+delta));const [node]=list.splice(i,1);list.splice(j,0,node);});}
  function duplicateLayer(){if(!layer)return;const copy=structuredClone(layer);const rename=(node:VisualNode)=>{node.id=id('layer');if(node.kind==='group')node.children.forEach(rename);};rename(copy);copy.label=(copy.label??copy.kind)+' copy';mutate(next=>listFor(next.scene,selected)?.push(copy));selected=copy.id;}
  function begin(event:PointerEvent,resize:boolean){if(saving||!selectedBounds||!layer||!stage||event.button!==0||!('x'in layer)||isExpression(layer.x)||isExpression(layer.y))return;const toLocal=renderedLayer(stage,layer.id)?.getScreenCTM()?.inverse();if(!toLocal||![toLocal.a,toLocal.b,toLocal.c,toLocal.d,toLocal.e,toLocal.f].every(Number.isFinite))return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(toLocal);event.preventDefault();drag={pointer:event.pointerId,x:point.x,y:point.y,toLocal,original:{x:numeric(layer.x),y:numeric(layer.y),width:'width'in layer?numeric(layer.width):0,height:'height'in layer?numeric(layer.height):0},resize,history};(event.currentTarget as Element).setPointerCapture(event.pointerId);}
  function move(event:PointerEvent){if(saving||!drag||drag.pointer!==event.pointerId)return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(drag.toLocal),dx=point.x-drag.x,dy=point.y-drag.y;const original=drag.original;
    history=drag.history;patchNode(drag.resize?{width:Math.max(1,Math.round(original.width+dx)),height:Math.max(1,Math.round(original.height+dy))}:{x:Math.round(original.x+dx),y:Math.round(original.y+dy)});
  }
  function undo(){if(saving)return;history=undoSource(history);invalidate();}function redo(){if(saving)return;history=redoSource(history);invalidate();}
  function keyboard(event:KeyboardEvent){if(!dialog?.open||saving)return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo();}}
  async function compile(){const generation=++build,identity=compileIdentity(),snapshot=structuredClone(draft);busy=true;error='';compiled=undefined;try{const result=await fence.run(identity,signal=>compileWidget(snapshot,{width:targetWidth,height:targetHeight,motion,audio:audioEnabled,capabilities:BROWSER_WIDGET_CAPABILITIES,signal,onProgress:p=>{if(generation===build)progress=`${p.phase} ${p.completed}/${p.total}`;}}));if(result&&generation===build){compiled=result;progress='Compilation complete';}}catch(e){if(generation===build)error=e instanceof Error?e.message:String(e);}finally{if(generation===build)busy=false;}}
  async function save(){if(!compiled||fence.get(compileIdentity())!==compiled)return; saving=true;error='';try{await onsave(structuredClone(draft),compiled);}catch(e){error=e instanceof Error?e.message:String(e);}finally{saving=false;}}
  function cancel(){if(history.past.length&&!window.confirm('Discard unsaved design changes?'))return;invalidate();oncancel();}
  function download(){if(!compiled||fence.get(compileIdentity())!==compiled)return;const url=URL.createObjectURL(new Blob([JSON.stringify(compiled)],{type:'application/json'})),anchor=document.createElement('a');anchor.href=url;anchor.download=`${draft.id}.compiled-widget.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function addSignal(){mutate(next=>{next.behavior.signals.push({id:id('signal'),source:'local',type:'boolean',initial:false});});}
  function changeSignalType(index:number,type:string){mutate(next=>{const previous=next.behavior.signals[index];next.behavior.signals[index]={id:previous.id,source:previous.source,type:type as 'boolean',initial:type==='number'?0:type==='enum'?'off':false,...(type==='number'?{min:0,max:100}:type==='enum'?{values:['off','on']}:{})} as BehaviorSignal;});}
  function signalSource(index:number,source:string){mutate(next=>{const signal=next.behavior.signals[index];signal.source=source as BehaviorSignal['source'];if(source!=='feedback'){delete signal.freshnessMs;delete signal.qualitySignal;delete signal.requireGameConfirmed;}});}
  function scalar(signal:BehaviorSignal,value:string):Scalar{return signal.type==='boolean'?value==='true':signal.type==='number'?Number(value):value;}
  function addPort(direction:'inputs'|'outputs'){const signal=draft.behavior.signals.find(s=>direction==='inputs'?s.source==='local':s.source==='feedback');if(!signal){error=direction==='inputs'?'Add a local requested signal first.':'Add a feedback signal first.';return;}mutate(next=>{const portId=id(direction==='inputs'?'input':'output'),domain=signal.type==='number'?{min:signal.min,max:signal.max}:signal.type==='enum'?{values:signal.values}:{};next[direction].push({id:portId,label:'Port',signal:signal.id,type:signal.type,...domain});if(direction==='inputs')(next.behavior.outputs??=[]).push({id:portId,type:signal.type,neutral:signal.initial,...domain} as NonNullable<WidgetSource['behavior']['outputs']>[number]);});}
  function portSignal(direction:'inputs'|'outputs',index:number,signalId:string){mutate(next=>{const signal=next.behavior.signals.find(s=>s.id===signalId)!,port=next[direction][index],domain=signal.type==='number'?{min:signal.min,max:signal.max}:signal.type==='enum'?{values:signal.values}:{};next[direction][index]={id:port.id,label:port.label,signal:signal.id,type:signal.type,...domain};if(direction==='inputs'){next.behavior.outputs=(next.behavior.outputs??[]).filter(output=>output.id!==port.id);next.behavior.outputs.push({id:port.id,type:signal.type,neutral:signal.initial,...domain} as NonNullable<WidgetSource['behavior']['outputs']>[number]);}});}
  function addParameter(){mutate(next=>next.parameters.push({id:id('parameter'),label:'Parameter',type:'number',default:0,min:0,max:100}));}
  function parameterType(index:number,type:string){mutate(next=>{const previous=next.parameters[index];next.parameters[index]={id:previous.id,label:previous.label,type,default:type==='number'?0:type==='boolean'?false:type==='color'?'#72d8ca':'Label',...(type==='number'?{min:0,max:100}:{})} as WidgetParameter;});}
  function addRegion(){mutate(next=>next.behavior.regions.push({id:id('region'),initial:'idle',states:['idle','active'],transitions:[]}));}
  function outputType(index:number,type:string){mutate(next=>{const previous=next.behavior.outputs![index];next.behavior.outputs![index]={id:previous.id,type:type as 'boolean',neutral:type==='number'?0:type==='enum'?'off':false,...(type==='number'?{min:0,max:100}:type==='enum'?{values:['off','on']}:{})} as NonNullable<WidgetSource['behavior']['outputs']>[number];});}
  function addTransition(regionIndex:number){mutate(next=>{const region=next.behavior.regions[regionIndex];region.transitions.push({id:id('transition'),from:region.initial,event:next.behavior.events[0]?.id??'activate',to:region.states[1]??region.initial,actions:[]});});}
  function defaultAction(type:string):BehaviorAction{return type==='set'?{type:'set',signal:draft.behavior.signals.find(signal=>signal.source==='local')?.id??'',value:{literal:false}}:type==='emit'?{type:'emit',port:draft.behavior.outputs?.[0]?.id??'',value:{literal:false}}:type==='cue'?{type:'cue',cue:draft.sounds?.[0]?.cue??'click'}:{type:type as 'start-timer',timer:draft.behavior.timers?.[0]?.id??''};}
  async function importAsset(file?:File){if(!file)return;try{if(file.size>2*1024*1024)throw Error('Assets must be at most 2 MiB.');if(!['image/png','image/jpeg','image/webp','audio/wav','audio/x-wav'].includes(file.type))throw Error('Use PNG, JPEG, WebP or PCM16 WAV.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));mutate(next=>{(next.assets??=[]).push({id:id('asset'),mime:(file.type==='audio/x-wav'?'audio/wav':file.type) as 'audio/wav',base64:btoa(binary)});});}catch(e){error=e instanceof Error?e.message:String(e);}}
  function simulation(event:string){const declaration=draft.behavior.events.find(item=>item.id===event);const updates:Record<string,Scalar>={},feedback:Record<string,BehaviorFeedback>={};for(const signal of draft.behavior.signals){if(!declaration?.updates?.includes(signal.id))continue;if(signal.source==='input')updates[signal.id]=inputValues[signal.id]??signal.initial;else if(signal.source==='feedback'){const status=(qualities[signal.id]??'unknown') as BehaviorFeedback['status'];feedback[signal.id]={status,...(status==='fresh'||status==='stale'?{value:feedbackValues[signal.id]??signal.initial,provenance:'game-confirmed',sourceKind:'simulator'}:{})};}}tryPlayer?.dispatch(event,updates,feedback);}
  onMount(()=>{dialog.showModal();return()=>{fence.invalidate();dialog.close();};});
</script>

<svelte:window onkeydown={keyboard}/>
<dialog class="generic-designer" bind:this={dialog} aria-label="Generic widget designer" oncancel={event=>{event.preventDefault();cancel();}}>
  <header><div><span class="eyebrow">WIDGET DESIGNER</span><input class="title" aria-label="Widget name" disabled={saving} value={draft.title} onchange={e=>mutate(next=>next.title=e.currentTarget.value)}/><p>Design visuals, configure behavior, compile finished pixels.</p></div><div class="actions"><button title="Undo" aria-label="Undo" disabled={!history.past.length||saving} onclick={undo}><Icon name="undo" size={16}/></button><button title="Redo" aria-label="Redo" disabled={!history.future.length||saving} onclick={redo}><Icon name="redo" size={16}/></button><button onclick={cancel} disabled={saving}><Icon name="close" size={16}/>Cancel</button><button onclick={save} disabled={!compiled||busy||saving}><Icon name="save" size={16}/>{saving?'Saving…':'Save'}</button></div></header>
  <nav aria-label="Designer workspaces">{#each tabs as workspace}<button class:active={tab===workspace} aria-pressed={tab===workspace} onclick={()=>tab=workspace}><Icon name={({Design:'pencil',Data:'sliders',Behavior:'layout',Motion:'play',Sound:'activity',Try:'monitor'} as Record<string,string>)[workspace]} size={16}/>{workspace}</button>{/each}</nav>
  <div class="buildbar" inert={saving}><label>Target width<input aria-label="Compiled width" type="number" min="1" max="2048" value={targetWidth} onchange={e=>{targetWidth=e.currentTarget.valueAsNumber;invalidate();}}/></label><label>Height<input aria-label="Compiled height" type="number" min="1" max="2048" value={targetHeight} onchange={e=>{targetHeight=e.currentTarget.valueAsNumber;invalidate();}}/></label><label class="check"><input type="checkbox" bind:checked={motion} onchange={invalidate}/>Animation</label><label class="check"><input type="checkbox" bind:checked={audioEnabled} onchange={invalidate}/>Audio</label><button class="primary" onclick={()=>void compile()} disabled={busy||saving}><Icon name="zap" size={16}/>Compile</button>{#if busy}<button onclick={invalidate}><Icon name="stop" size={16}/>Cancel</button>{/if}<button onclick={download} disabled={!compiled||busy}><Icon name="download" size={16}/>Export</button><span role="status">{progress||(!compiled?'Compile required':'Compiled')}</span></div>
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  <div class="workspace" inert={saving} class:design={tab==='Design'}>
  {#if tab==='Design'}
    <aside aria-label="Layers"><h3>Layers <small>back to front</small></h3><ol class="layers">{#each layerList as entry (entry.node.id)}<li><button class:active={selected===entry.node.id} style:padding-left={`${8+entry.depth*14}px`} onclick={()=>selected=entry.node.id}><Icon name={entry.node.kind==='group'?'folder':entry.node.kind==='image'?'image':'pencil'} size={14}/><span>{entry.node.label??entry.node.id}<small>{entry.node.kind}</small></span></button></li>{/each}</ol><label>Primitive<select aria-label="New primitive" bind:value={newKind}>{#each ['rectangle','ellipse','line','path','text','image','group'] as kind}<option value={kind}>{kind}</option>{/each}</select></label><label>Parent group<select bind:value={parentId}><option value="">Scene</option>{#each layerList.filter(item=>item.node.kind==='group') as item}<option value={item.node.id}>{item.node.label??item.node.id}</option>{/each}</select></label><button onclick={addLayer}><Icon name="plus" size={14}/>Add</button><div class="actions wrap"><button disabled={!layer} onclick={()=>reorderLayer(-1)}><Icon name="back" size={14}/>Back</button><button disabled={!layer} onclick={()=>reorderLayer(1)}><Icon name="arrow" size={14}/>Forward</button><button disabled={!layer} onclick={duplicateLayer}><Icon name="copy" size={14}/>Duplicate</button><button disabled={!layer} onclick={removeLayer}><Icon name="trash" size={14}/>Delete</button></div><h3>Canvas</h3><div class="two"><label>Width<input type="number" value={draft.size.width} onchange={e=>mutate(next=>next.size.width=e.currentTarget.valueAsNumber)}/></label><label>Height<input type="number" value={draft.size.height} onchange={e=>mutate(next=>next.size.height=e.currentTarget.valueAsNumber)}/></label></div><label>Import artwork<input type="file" accept="image/png,image/jpeg,image/webp" onchange={e=>{void importAsset(e.currentTarget.files?.[0]);e.currentTarget.value='';}}/></label></aside>
    <main class="design-canvas"><p class="hint">Authoring preview · layers are compiled before playback.</p>
      <details><summary>Preview presentation</summary><div class="two">{#each draft.behavior.regions as region}<label>{region.id}<select value={previewRegions[region.id]} onchange={e=>designRegions={...designRegions,[region.id]:e.currentTarget.value}}>{#each region.states as state}<option value={state}>{state}</option>{/each}</select></label>{/each}{#each draft.visualDomains as domain}{@const signal=draft.behavior.signals.find(s=>s.id===domain.signal)}{#if signal}<label>{signal.id}{#if signal.type==='number'}<input type="number" min={signal.min} max={signal.max} value={Number(designValues[signal.id])} onchange={e=>designOverrides={...designOverrides,[signal.id]:e.currentTarget.valueAsNumber}}/>{:else}<select value={String(designValues[signal.id])} onchange={e=>designOverrides={...designOverrides,[signal.id]:scalar(signal,e.currentTarget.value)}}>{#each (signal.type==='boolean'?[false,true]:signal.values) as value}<option value={String(value)}>{String(value)}</option>{/each}</select>{/if}</label>{/if}{/each}</div></details>
      <svg bind:this={stage} viewBox={`0 0 ${draft.size.width} ${draft.size.height}`} aria-label="Source design canvas" style:aspect-ratio={`${draft.size.width}/${draft.size.height}`}>
      {#each draft.scene as node (node.id)}<GenericSceneNode {node} values={designValues} regions={previewRegions} assets={draft.assets}/>{/each}
      {#if selectedBounds && layer}<g class="selection" transform={selection?.transform}><rect x={selectedBounds.x} y={selectedBounds.y} width={Math.max(1,selectedBounds.width)} height={Math.max(1,selectedBounds.height)} fill="transparent" stroke="#96ddce" stroke-width="1" stroke-dasharray="4 3" vector-effect="non-scaling-stroke" onpointerdown={e=>begin(e,false)} onpointermove={move} onpointerup={()=>drag=undefined} onpointercancel={()=>drag=undefined} role="presentation"/>{#if 'width'in layer}<rect x={selectedBounds.x+selectedBounds.width-4} y={selectedBounds.y+selectedBounds.height-4} width="8" height="8" fill="#96ddce" stroke="#183b3c" onpointerdown={e=>begin(e,true)} onpointermove={move} onpointerup={()=>drag=undefined} onpointercancel={()=>drag=undefined} role="presentation"/>{/if}</g>{/if}
    </svg><p class="hint">Select a primitive to move or resize it. Expressions can bind geometry, paint and transforms to finite data.</p></main>
    <aside aria-label="Layer properties">{#if layer}<h3>{layer.kind}</h3><label>Name<input value={layer.label??''} onchange={e=>patchNode({label:e.currentTarget.value})}/></label>
      {#each ['x','y','width','height','x2','y2','radius','fontSize'] as field}{#if field in layer}<div class="property"><label>{field}{#if !isExpression(nodeValue(field))}<input aria-label={`Layer ${field}`} type="number" value={Number(nodeValue(field))} onchange={e=>patchNode({[field]:e.currentTarget.valueAsNumber})}/>{/if}</label><button title={`Bind ${field}`} aria-label={`Bind ${field}`} onclick={()=>patchNode({[field]:isExpression(nodeValue(field))?numeric(nodeValue(field)):{ref:references[0]??''}})}><Icon name="link" size={14}/></button></div>{#if isExpression(nodeValue(field))}<GenericExpression value={expr(nodeValue(field))} {references} regions={regionIds} label={field} onchange={v=>patchNode({[field]:v})}/>{/if}{/if}{/each}
      {#each ['fill','stroke','strokeWidth','opacity','visible'] as field}<details><summary>{field}</summary><GenericExpression value={expr(nodeValue(field)??(field==='visible'?true:field==='opacity'?1:field==='strokeWidth'?0:'#72d8ca'))} {references} regions={regionIds} label={field} onchange={v=>patchNode({[field]:'literal'in v?v.literal:v})}/></details>{/each}
      {#if layer.kind==='text'}<label>Text<input aria-label="Layer text" value={typeof layer.text==='string'?layer.text:''} onchange={e=>patchNode({text:e.currentTarget.value})}/></label><details><summary>Text expression</summary><GenericExpression value={expr(layer.text)} {references} regions={regionIds} label="Text" onchange={v=>patchNode({text:'literal'in v?v.literal:v})}/></details><label>Font<select value={layer.font} onchange={e=>patchNode({font:e.currentTarget.value})}><option value="sans">Sans</option><option value="mono">Mono</option></select></label><label>Align<select value={layer.align??'left'} onchange={e=>patchNode({align:e.currentTarget.value})}><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label>{/if}
      {#if layer.kind==='path'}<label>Path data<textarea aria-label="Path data" value={typeof layer.d==='string'?layer.d:''} onchange={e=>patchNode({d:e.currentTarget.value})}></textarea></label>{/if}
      {#if layer.kind==='image'}<label>Artwork<select aria-label="Layer artwork" value={layer.assetId} onchange={e=>patchNode({assetId:e.currentTarget.value})}><option value="">Choose</option>{#each (draft.assets??[]).filter(a=>a.mime.startsWith('image/')) as asset}<option value={asset.id}>{asset.id}</option>{/each}</select></label>{/if}
      <details><summary>Transform</summary>{#each ['translateX','translateY','rotate','scaleX','scaleY','originX','originY'] as field}<GenericExpression value={expr((layer.transform as Record<string,unknown>|undefined)?.[field]??(field.startsWith('scale')?1:0))} {references} regions={regionIds} label={field} onchange={v=>patchNode({transform:{...layer?.transform,[field]:'literal'in v?v.literal:v}})}/>{/each}</details>
    {:else}<p>Select a layer.</p>{/if}
    <h3>Parameters</h3>{#each draft.parameters as parameter,i}<details><summary>{parameter.label}</summary><label>ID<input value={parameter.id} onchange={e=>mutate(next=>next.parameters[i].id=e.currentTarget.value)}/></label><label>Label<input value={parameter.label} onchange={e=>mutate(next=>next.parameters[i].label=e.currentTarget.value)}/></label><label>Type<select value={parameter.type} onchange={e=>parameterType(i,e.currentTarget.value)}>{#each ['text','color','number','boolean'] as type}<option value={type}>{type}</option>{/each}</select></label>{#if parameter.type==='boolean'}<label class="check"><input type="checkbox" checked={parameter.default} onchange={e=>mutate(next=>next.parameters[i].default=e.currentTarget.checked)}/>Default</label>{:else}<label>Default<input type={parameter.type==='number'?'number':parameter.type==='color'?'color':'text'} value={String(parameter.default)} onchange={e=>mutate(next=>next.parameters[i].default=parameter.type==='number'?e.currentTarget.valueAsNumber:e.currentTarget.value)}/></label>{/if}{#if parameter.type==='number'}<div class="two"><label>Minimum<input type="number" value={parameter.min} onchange={e=>mutate(next=>Object.assign(next.parameters[i],{min:e.currentTarget.valueAsNumber}))}/></label><label>Maximum<input type="number" value={parameter.max} onchange={e=>mutate(next=>Object.assign(next.parameters[i],{max:e.currentTarget.valueAsNumber}))}/></label></div>{/if}<button onclick={()=>mutate(next=>next.parameters.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></details>{/each}<button onclick={addParameter}><Icon name="plus" size={14}/>Add</button></aside>
  {:else if tab==='Data'}
    <main class="form-grid"><section><h3>Typed signals</h3><p class="hint">Local intent, external input and simulator feedback remain independent.</p>{#each draft.behavior.signals as signal,i}<article><div class="two"><label>ID<input value={signal.id} onchange={e=>mutate(next=>next.behavior.signals[i].id=e.currentTarget.value)}/></label><label>Source<select value={signal.source} onchange={e=>signalSource(i,e.currentTarget.value)}><option value="local">Local state</option><option value="input">External input</option><option value="feedback">Feedback</option></select></label></div><label>Type<select value={signal.type} onchange={e=>changeSignalType(i,e.currentTarget.value)}>{#each ['boolean','number','enum'] as type}<option value={type}>{type}</option>{/each}</select></label>{#if signal.type==='boolean'}<label>Initial<select value={String(signal.initial)} onchange={e=>mutate(next=>next.behavior.signals[i].initial=e.currentTarget.value==='true')}><option value="false">False</option><option value="true">True</option></select></label>{:else}<label>Initial<input type={signal.type==='number'?'number':'text'} value={String(signal.initial)} onchange={e=>mutate(next=>next.behavior.signals[i].initial=scalar(signal,e.currentTarget.value))}/></label>{/if}{#if signal.type==='number'}<div class="two"><label>Minimum<input type="number" value={signal.min} onchange={e=>mutate(next=>Object.assign(next.behavior.signals[i],{min:e.currentTarget.valueAsNumber}))}/></label><label>Maximum<input type="number" value={signal.max} onchange={e=>mutate(next=>Object.assign(next.behavior.signals[i],{max:e.currentTarget.valueAsNumber}))}/></label></div>{:else if signal.type==='enum'}<label>Values (comma separated)<input value={signal.values.join(', ')} onchange={e=>mutate(next=>Object.assign(next.behavior.signals[i],{values:e.currentTarget.value.split(',').map(v=>v.trim()).filter(Boolean)}))}/></label>{/if}{#if signal.source==='feedback'}<label>Fresh for (ms)<input type="number" value={signal.freshnessMs??1000} onchange={e=>mutate(next=>next.behavior.signals[i].freshnessMs=e.currentTarget.valueAsNumber)}/></label><label>Quality signal<select value={signal.qualitySignal??''} onchange={e=>mutate(next=>{if(e.currentTarget.value)next.behavior.signals[i].qualitySignal=e.currentTarget.value;else delete next.behavior.signals[i].qualitySignal;})}><option value="">None</option>{#each draft.behavior.signals.filter(s=>s.type==='enum') as item}<option value={item.id}>{item.id}</option>{/each}</select></label><label class="check"><input type="checkbox" checked={signal.requireGameConfirmed??false} onchange={e=>mutate(next=>next.behavior.signals[i].requireGameConfirmed=e.currentTarget.checked)}/>Require game confirmation</label>{/if}<button onclick={()=>mutate(next=>next.behavior.signals.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={addSignal}><Icon name="plus" size={14}/>Add</button></section>
    <section><h3>Finite visual domains</h3><p class="hint">Only these sampled values produce images. Semantic rules still receive the original value.</p>{#each draft.visualDomains as domain,i}<article><label>Signal<select value={domain.signal} onchange={e=>mutate(next=>next.visualDomains[i].signal=e.currentTarget.value)}>{#each draft.behavior.signals as signal}<option value={signal.id}>{signal.id}</option>{/each}</select></label>{#if draft.behavior.signals.find(s=>s.id===domain.signal)?.type==='number'}<div class="two">{#each ['min','max','samples','maxErrorPixels','travelPixels','smoothingMs'] as field}<label>{field}<input type="number" value={(domain as unknown as Record<string,number>)[field]??0} onchange={e=>mutate(next=>Object.assign(next.visualDomains[i],{[field]:e.currentTarget.valueAsNumber}))}/></label>{/each}</div>{:else}<p>{(domain.values??[]).map(String).join(', ')}</p>{/if}<button onclick={()=>mutate(next=>next.visualDomains.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>{const signal=next.behavior.signals.find(s=>!next.visualDomains.some(d=>d.signal===s.id));if(signal)next.visualDomains.push(signal.type==='number'?{signal:signal.id,min:signal.min,max:signal.max,samples:11,maxErrorPixels:1,travelPixels:100}:{signal:signal.id,values:signal.type==='boolean'?[false,true]:signal.values});})}><Icon name="plus" size={14}/>Add</button>
    {#each ['inputs','outputs'] as direction}<h3>{direction==='inputs'?'Input ports':'Output ports'}</h3>{#each draft[direction as 'inputs'|'outputs'] as port,i}<article><div class="two"><label>ID<input value={port.id} onchange={e=>mutate(next=>next[direction as 'inputs'|'outputs'][i].id=e.currentTarget.value)}/></label><label>Label<input value={port.label} onchange={e=>mutate(next=>next[direction as 'inputs'|'outputs'][i].label=e.currentTarget.value)}/></label></div><label>Signal<select value={port.signal} onchange={e=>portSignal(direction as 'inputs'|'outputs',i,e.currentTarget.value)}>{#each draft.behavior.signals as signal}<option value={signal.id}>{signal.id}</option>{/each}</select></label><button onclick={()=>mutate(next=>next[direction as 'inputs'|'outputs'].splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>addPort(direction as 'inputs'|'outputs')}><Icon name="plus" size={14}/>Add</button>{/each}</section></main>
  {:else if tab==='Behavior'}
    <main class="form-grid"><section><h3>Events</h3>{#each draft.behavior.events as event,i}<article><label>ID<input value={event.id} onchange={e=>mutate(next=>next.behavior.events[i].id=e.currentTarget.value)}/></label><p class="hint">Signals this event may update</p>{#each draft.behavior.signals.filter(s=>s.source!=='local') as signal}<label class="check"><input type="checkbox" checked={event.updates?.includes(signal.id)??false} onchange={e=>mutate(next=>{const values=new Set(next.behavior.events[i].updates??[]);e.currentTarget.checked?values.add(signal.id):values.delete(signal.id);next.behavior.events[i].updates=[...values];})}/>{signal.id}</label>{/each}<button onclick={()=>mutate(next=>next.behavior.events.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>next.behavior.events.push({id:id('event')}))}><Icon name="plus" size={14}/>Add</button>
    <h3>Output bindings</h3><p class="hint">Emit actions use these typed ports; reset sends their neutral values.</p>{#each draft.behavior.outputs??[] as output,i}<article><label>ID<input value={output.id} onchange={e=>mutate(next=>next.behavior.outputs![i].id=e.currentTarget.value)}/></label><label>Type<select value={output.type} onchange={e=>outputType(i,e.currentTarget.value)}><option value="boolean">Boolean</option><option value="number">Number</option><option value="enum">Enum</option></select></label>{#if output.type==="number"}<div class="two"><label>Minimum<input type="number" value={output.min} onchange={e=>mutate(next=>Object.assign(next.behavior.outputs![i],{min:e.currentTarget.valueAsNumber}))}/></label><label>Maximum<input type="number" value={output.max} onchange={e=>mutate(next=>Object.assign(next.behavior.outputs![i],{max:e.currentTarget.valueAsNumber}))}/></label></div>{:else if output.type==="enum"}<label>Values<input value={output.values.join(", ")} onchange={e=>mutate(next=>Object.assign(next.behavior.outputs![i],{values:e.currentTarget.value.split(",").map(v=>v.trim()).filter(Boolean)}))}/></label>{/if}<label>Neutral<input value={String(output.neutral)} onchange={e=>mutate(next=>next.behavior.outputs![i].neutral=output.type==='boolean'?e.currentTarget.value==='true':output.type==='number'?Number(e.currentTarget.value):e.currentTarget.value)}/></label><small>{output.type}</small><button onclick={()=>mutate(next=>next.behavior.outputs!.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>(next.behavior.outputs??=[]).push({id:id('output'),type:'boolean',neutral:false}))}><Icon name="plus" size={14}/>Add</button>
    <h3>Timers</h3>{#each draft.behavior.timers??[] as timer,i}<article><label>ID<input value={timer.id} onchange={e=>mutate(next=>next.behavior.timers![i].id=e.currentTarget.value)}/></label><label>Event<select value={timer.event} onchange={e=>mutate(next=>next.behavior.timers![i].event=e.currentTarget.value)}>{#each draft.behavior.events as event}<option value={event.id}>{event.id}</option>{/each}</select></label><label>Delay (ms)<input type="number" min="1" value={timer.delayMs} onchange={e=>mutate(next=>next.behavior.timers![i].delayMs=e.currentTarget.valueAsNumber)}/></label><label class="check"><input type="checkbox" checked={timer.repeat??false} onchange={e=>mutate(next=>next.behavior.timers![i].repeat=e.currentTarget.checked)}/>Repeat</label><button onclick={()=>mutate(next=>next.behavior.timers!.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>(next.behavior.timers??=[]).push({id:id('timer'),event:next.behavior.events[0]?.id??'',delayMs:1000}))}><Icon name="plus" size={14}/>Add</button>
    <h3>Hit regions</h3>{#each draft.hitRegions as hit,i}<article><label>ID<input value={hit.id} onchange={e=>mutate(next=>next.hitRegions[i].id=e.currentTarget.value)}/></label><div class="two">{#each ['x','y','width','height'] as field}<label>{field}<input type="number" value={(hit as unknown as Record<string,number>)[field]} onchange={e=>mutate(next=>Object.assign(next.hitRegions[i],{[field]:e.currentTarget.valueAsNumber}))}/></label>{/each}</div>{#each ['press','release','activate','cancel'] as phase}<label>{phase}<select value={hit.events[phase as 'press']??''} onchange={e=>mutate(next=>{if(e.currentTarget.value)next.hitRegions[i].events[phase as 'press']=e.currentTarget.value;else delete next.hitRegions[i].events[phase as 'press'];})}><option value="">No event</option>{#each draft.behavior.events as event}<option value={event.id}>{event.id}</option>{/each}</select></label>{/each}<button onclick={()=>mutate(next=>next.hitRegions.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>next.hitRegions.push({id:id('hit'),x:0,y:0,width:next.size.width,height:next.size.height,events:{}}))}><Icon name="plus" size={14}/>Add</button></section>
    <section><h3>Independent state regions</h3><p class="hint">Each region handles the same event snapshot. Higher priority guarded transitions win.</p>{#each draft.behavior.regions as region,ri}<article><div class="two"><label>ID<input value={region.id} onchange={e=>mutate(next=>next.behavior.regions[ri].id=e.currentTarget.value)}/></label><label>Initial<select value={region.initial} onchange={e=>mutate(next=>next.behavior.regions[ri].initial=e.currentTarget.value)}>{#each region.states as state}<option value={state}>{state}</option>{/each}</select></label></div><label>States (comma separated)<input value={region.states.join(', ')} onchange={e=>mutate(next=>next.behavior.regions[ri].states=e.currentTarget.value.split(',').map(s=>s.trim()).filter(Boolean))}/></label>
    {#each region.transitions as transition,ti}<details><summary>{transition.id}: {transition.from} → {transition.to??transition.from}</summary><label>ID<input value={transition.id} onchange={e=>mutate(next=>next.behavior.regions[ri].transitions[ti].id=e.currentTarget.value)}/></label><div class="two"><label>From<select value={transition.from} onchange={e=>mutate(next=>next.behavior.regions[ri].transitions[ti].from=e.currentTarget.value)}><option value="*">Any</option>{#each region.states as state}<option value={state}>{state}</option>{/each}</select></label><label>To<select value={transition.to??''} onchange={e=>mutate(next=>{if(e.currentTarget.value)next.behavior.regions[ri].transitions[ti].to=e.currentTarget.value;else delete next.behavior.regions[ri].transitions[ti].to;})}><option value="">Stay</option>{#each region.states as state}<option value={state}>{state}</option>{/each}</select></label></div><label>On event<select value={transition.event} onchange={e=>mutate(next=>next.behavior.regions[ri].transitions[ti].event=e.currentTarget.value)}>{#each draft.behavior.events as event}<option value={event.id}>{event.id}</option>{/each}</select></label><label>Priority<input type="number" value={transition.priority??0} onchange={e=>mutate(next=>next.behavior.regions[ri].transitions[ti].priority=e.currentTarget.valueAsNumber)}/></label><GenericExpression value={transition.guard??{literal:true}} references={draft.behavior.signals.map(s=>s.id)} regions={regionIds} label="Guard" onchange={v=>mutate(next=>next.behavior.regions[ri].transitions[ti].guard=v)}/>
    {#each transition.actions??[] as action,ai}<div class="action-editor"><label>Action<select value={action.type} onchange={e=>mutate(next=>next.behavior.regions[ri].transitions[ti].actions![ai]=defaultAction(e.currentTarget.value))}>{#each ['set','emit','cue','start-timer','cancel-timer'] as type}<option value={type}>{type}</option>{/each}</select></label>{#if action.type==='set'||action.type==='emit'}<label>Target<select value={action.type==='set'?action.signal:action.port} onchange={e=>mutate(next=>Object.assign(next.behavior.regions[ri].transitions[ti].actions![ai],{[action.type==='set'?'signal':'port']:e.currentTarget.value}))}>{#each (action.type==='set'?draft.behavior.signals.filter(s=>s.source==='local'):(draft.behavior.outputs??[])) as target}<option value={target.id}>{target.id}</option>{/each}</select></label><GenericExpression value={action.value} references={draft.behavior.signals.map(s=>s.id)} regions={regionIds} label="Action value" onchange={v=>mutate(next=>Object.assign(next.behavior.regions[ri].transitions[ti].actions![ai],{value:v}))}/>{:else if action.type==='cue'}<label>Cue<input value={action.cue} onchange={e=>mutate(next=>Object.assign(next.behavior.regions[ri].transitions[ti].actions![ai],{cue:e.currentTarget.value}))}/></label>{:else}<label>Timer<select value={action.timer} onchange={e=>mutate(next=>Object.assign(next.behavior.regions[ri].transitions[ti].actions![ai],{timer:e.currentTarget.value}))}>{#each draft.behavior.timers??[] as timer}<option value={timer.id}>{timer.id}</option>{/each}</select></label>{/if}<button onclick={()=>mutate(next=>next.behavior.regions[ri].transitions[ti].actions!.splice(ai,1))}><Icon name="trash" size={14}/>Delete action</button></div>{/each}<button onclick={()=>mutate(next=>(next.behavior.regions[ri].transitions[ti].actions??=[]).push(defaultAction('set')))}><Icon name="plus" size={14}/>Add action</button><button onclick={()=>mutate(next=>next.behavior.regions[ri].transitions.splice(ti,1))}><Icon name="trash" size={14}/>Delete transition</button></details>{/each}<button onclick={()=>addTransition(ri)}><Icon name="plus" size={14}/>Add transition</button><button onclick={()=>mutate(next=>next.behavior.regions.splice(ri,1))}><Icon name="trash" size={14}/>Delete region</button></article>{/each}<button onclick={addRegion}><Icon name="plus" size={14}/>Add</button></section></main>
  {:else if tab==='Motion'}
    <main class="form-grid"><section><h3>Baked transitions</h3><p class="hint">Tracks become finished image frames. Disabling animation preserves semantic outputs.</p>{#each draft.motions??[] as clip,ci}<article><label>ID<input value={clip.id} onchange={e=>mutate(next=>next.motions![ci].id=e.currentTarget.value)}/></label><div class="two"><label>Duration (ms)<input type="number" value={clip.durationMs} onchange={e=>mutate(next=>next.motions![ci].durationMs=e.currentTarget.valueAsNumber)}/></label><label>Frames / second<input type="number" value={clip.fps} onchange={e=>mutate(next=>next.motions![ci].fps=e.currentTarget.valueAsNumber)}/></label></div><label>Interruption<select value={clip.interruption??'snap'} onchange={e=>mutate(next=>next.motions![ci].interruption=e.currentTarget.value as 'snap')}><option value="reverse">Reverse from current progress</option><option value="restart">Restart explicit route</option><option value="snap">Snap to target</option></select></label>{#each ['from','to'] as end}<h4>{end}</h4>{#each draft.behavior.signals as signal}<label class="check"><input type="checkbox" checked={signal.id in clip[end as 'from']} onchange={e=>mutate(next=>{if(e.currentTarget.checked)next.motions![ci][end as 'from'][signal.id]=signal.initial;else delete next.motions![ci][end as 'from'][signal.id];})}/>{signal.id}</label>{#if signal.id in clip[end as 'from']}<input aria-label={`${end} ${signal.id}`} value={String(clip[end as 'from'][signal.id])} onchange={e=>mutate(next=>next.motions![ci][end as 'from'][signal.id]=scalar(signal,e.currentTarget.value))}/>{/if}{/each}{#each draft.behavior.regions as region}<label>{region.id} state<select value={clip[end==="from"?"fromRegions":"toRegions"]?.[region.id]??""} onchange={e=>mutate(next=>{const key=end==="from"?"fromRegions":"toRegions";const states=next.motions![ci][key]??={};if(e.currentTarget.value)states[region.id]=e.currentTarget.value;else delete states[region.id];})}><option value="">Keep region</option>{#each region.states as state}<option value={state}>{state}</option>{/each}</select></label>{/each}{/each}
    {#each clip.tracks as track,ti}<details open><summary>{track.node} · {track.property}</summary><label>Layer<select value={track.node} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].node=e.currentTarget.value)}>{#each layerList as entry}<option value={entry.node.id}>{entry.node.label??entry.node.id}</option>{/each}</select></label><label>Property<select value={track.property} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].property=e.currentTarget.value)}>{#each ['x','y','width','height','radius','opacity','strokeWidth','transform.translateX','transform.translateY','transform.rotate','transform.scaleX','transform.scaleY'] as property}<option value={property}>{property}</option>{/each}</select></label><label>Easing<select value={track.easing??'linear'} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].easing=e.currentTarget.value as 'linear')}>{#each ['linear','ease-in','ease-out','ease-in-out'] as easing}<option value={easing}>{easing}</option>{/each}</select></label>{#each track.keyframes as keyframe,ki}<div class="three"><label>Time (0–1)<input type="number" min="0" max="1" step=".01" value={keyframe.at} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].keyframes[ki].at=e.currentTarget.valueAsNumber)}/></label><label>Value<input type="number" value={keyframe.value} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].keyframes[ki].value=e.currentTarget.valueAsNumber)}/></label><button title="Delete keyframe" aria-label="Delete keyframe" onclick={()=>mutate(next=>next.motions![ci].tracks[ti].keyframes.splice(ki,1))}><Icon name="trash" size={14}/></button></div>{/each}<button onclick={()=>mutate(next=>next.motions![ci].tracks[ti].keyframes.push({at:.5,value:0}))}><Icon name="plus" size={14}/>Add keyframe</button><button onclick={()=>mutate(next=>next.motions![ci].tracks.splice(ti,1))}><Icon name="trash" size={14}/>Delete track</button></details>{/each}<button onclick={()=>mutate(next=>next.motions![ci].tracks.push({node:layerList[0]?.node.id??'',property:'opacity',keyframes:[{at:0,value:0},{at:1,value:1}]}))}><Icon name="plus" size={14}/>Add track</button><button onclick={()=>mutate(next=>next.motions!.splice(ci,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>(next.motions??=[]).push({id:id('motion'),from:Object.fromEntries(next.visualDomains.map(d=>[d.signal,d.values?.[0]??d.min??0])),to:Object.fromEntries(next.visualDomains.map(d=>[d.signal,d.values?.at(-1)??d.max??1])),durationMs:200,fps:30,tracks:[],interruption:'snap'}))}><Icon name="plus" size={14}/>Add</button></section><section><h3>Playback rules</h3><p>Transition tracks modify authoring layers during compilation. The player receives their baked frame sequence, duration and interruption rule.</p><p>For rapidly changing gauges, use finite sampled images and direct value selection. Live values continue when animation is disabled.</p><p>Use Try to test rapid reversal, cancellation and reduced motion.</p></section></main>
  {:else if tab==='Sound'}
    <main class="form-grid"><section><h3>Optional sound cues</h3><p class="hint">Import PCM16 WAV, up to ten seconds. Silent visuals must communicate the same condition.</p><label>Import sound<input type="file" accept="audio/wav,.wav" onchange={e=>{void importAsset(e.currentTarget.files?.[0]);e.currentTarget.value='';}}/></label>{#each draft.sounds??[] as sound,i}<article><label>ID<input value={sound.id} onchange={e=>mutate(next=>next.sounds![i].id=e.currentTarget.value)}/></label><label>Behavior cue<input value={sound.cue} onchange={e=>mutate(next=>next.sounds![i].cue=e.currentTarget.value)}/></label><label>Audio asset<select value={sound.assetId} onchange={e=>mutate(next=>next.sounds![i].assetId=e.currentTarget.value)}><option value="">Choose</option>{#each (draft.assets??[]).filter(a=>a.mime==='audio/wav') as asset}<option value={asset.id}>{asset.id}</option>{/each}</select></label><div class="two"><label>Cooldown (ms)<input type="number" min="0" value={sound.cooldownMs??0} onchange={e=>mutate(next=>next.sounds![i].cooldownMs=e.currentTarget.valueAsNumber)}/></label><label>Volume (0–1)<input type="number" min="0" max="1" step=".1" value={sound.volume??1} onchange={e=>mutate(next=>next.sounds![i].volume=e.currentTarget.valueAsNumber)}/></label></div><label class="check"><input type="checkbox" checked={sound.stopOnExit??true} onchange={e=>mutate(next=>next.sounds![i].stopOnExit=e.currentTarget.checked)}/>Stop on state exit</label><button onclick={()=>mutate(next=>next.sounds!.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>(next.sounds??=[]).push({id:id('sound'),cue:'click',assetId:next.assets?.find(a=>a.mime==='audio/wav')?.id??'',cooldownMs:100,volume:1,stopOnExit:true}))}><Icon name="plus" size={14}/>Add</button></section><section><h3>Availability</h3><p>Audio capability controls compilation. Browser playback additionally requires a user gesture and respects mute and hidden-window state.</p><p>Cues received while unavailable are discarded. Unlocking, reconnecting or restoring a snapshot never replays old sound.</p><p>Add a cue action to a Behavior transition to trigger a sound.</p></section></main>
  {:else}
    <main class="try-layout">{#if compiled}<section class="try-canvas"><div style:aspect-ratio={`${compiled.artifact.width}/${compiled.artifact.height}`} style:width={`${compiled.artifact.width}px`}><CompiledWidget bind:this={tryPlayer} bundle={compiled} name={draft.title} {muted} showAudioControls onoutput={output=>outputs={...outputs,[output.port]:output.value}} onstate={state=>tryState=state}/></div><div class="actions"><button onclick={()=>tryPlayer?.reset()}><Icon name="refresh" size={14}/>Reset</button><label class="check"><input type="checkbox" bind:checked={muted}/>Mute</label></div><h3>Result</h3>{#if tryState}<dl>{#each Object.entries(tryState.values) as [key,value]}<div><dt>{key}</dt><dd>{String(value)}</dd></div>{/each}{#each Object.entries(tryState.regions) as [key,value]}<div><dt>State · {key}</dt><dd>{value}</dd></div>{/each}</dl>{/if}<h3>Emitted outputs</h3><dl>{#each Object.entries(outputs) as [key,value]}<div><dt>{key}</dt><dd>{String(value)}</dd></div>{/each}</dl></section><aside><h3>Simulate</h3><p class="hint">Requested state changes through the widget or events. Confirmation and quality are separate samples.</p>{#each draft.behavior.signals.filter(s=>s.source!=='local') as signal}<article><h4>{signal.id} · {signal.source}</h4>{#if signal.source==='feedback'}<label>Quality<select value={qualities[signal.id]??'unknown'} onchange={e=>qualities={...qualities,[signal.id]:e.currentTarget.value}}>{#each ['fresh','unknown','stale','disconnected'] as quality}<option value={quality}>{quality}</option>{/each}</select></label>{/if}<label>Value{#if signal.type==='boolean'||signal.type==='enum'}<select value={String((signal.source==='feedback'?feedbackValues:inputValues)[signal.id]??signal.initial)} onchange={e=>{if(signal.source==='feedback')feedbackValues={...feedbackValues,[signal.id]:scalar(signal,e.currentTarget.value)};else inputValues={...inputValues,[signal.id]:scalar(signal,e.currentTarget.value)};}}>{#each (signal.type==='boolean'?[false,true]:signal.values) as value}<option value={String(value)}>{String(value)}</option>{/each}</select>{:else}<input type="number" min={signal.min} max={signal.max} value={Number((signal.source==='feedback'?feedbackValues:inputValues)[signal.id]??signal.initial)} onchange={e=>{if(signal.source==='feedback')feedbackValues={...feedbackValues,[signal.id]:e.currentTarget.valueAsNumber};else inputValues={...inputValues,[signal.id]:e.currentTarget.valueAsNumber};}}/>{/if}</label></article>{/each}<label>Event<select bind:value={selectedEvent}>{#each draft.behavior.events as event}<option value={event.id}>{event.id}</option>{/each}</select></label><button onclick={()=>simulation(selectedEvent)}><Icon name="play" size={14}/>Send</button><CompiledArtifactInspector bundle={compiled} capabilities={BROWSER_WIDGET_CAPABILITIES}/></aside>{:else}<section class="empty"><Icon name="monitor" size={36}/><h3>Compile this design to try it</h3><p>Try plays only compiled image frames and behavior. Every source or target change invalidates the previous build.</p><button onclick={()=>void compile()} disabled={busy}><Icon name="zap" size={16}/>Compile</button></section>{/if}</main>
  {/if}
  </div>
</dialog>

<style>
  .generic-designer{width:min(1500px,97vw);height:min(1000px,96vh);max-width:none;max-height:none;padding:0;margin:auto;background:#101d26;color:#deecee;border:1px solid #38535f;border-radius:12px;box-shadow:0 25px 100px #000b;font:13px system-ui;overflow:hidden}.generic-designer::backdrop{background:#030b12c9}header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:15px 20px;border-bottom:1px solid #2f4652}.eyebrow{color:#8ed7c4;letter-spacing:.12em;font-size:10px}.title{display:block;font-size:22px;font-weight:600;border:0;background:transparent;padding:4px 0;width:100%;min-width:140px}header p{margin:3px 0 0;color:#8da6b3;font-size:11px}.actions{display:flex;gap:6px;align-items:center}.wrap{flex-wrap:wrap;margin-top:12px}button{display:inline-flex;align-items:center;justify-content:center;gap:6px;font:inherit;color:inherit;background:#233844;border:1px solid #3a5662;border-radius:5px;padding:7px 10px;cursor:pointer}button:hover{border-color:#83c8b7}button:disabled{opacity:.4;cursor:default}.primary{background:#295447;border-color:#659f88}button.active{background:#285347;border-color:#86cbb9}nav{display:flex;flex-direction:row;align-items:center;justify-content:flex-start;width:auto;min-height:0;gap:5px;padding:10px 18px;background:#14232d}nav button{width:auto;flex:0 0 auto;border:1px solid transparent;background:transparent}.buildbar{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:7px 18px;border-bottom:1px solid #2f4652;min-height:48px}.buildbar label{margin:0;font-size:10px}.buildbar input[type=number]{width:70px}.buildbar>span{font-size:10px;color:#9cb5bd}.workspace{height:calc(100% - 212px);overflow:auto;min-height:0}.workspace.design{display:grid;grid-template-columns:210px minmax(260px,1fr) 300px;overflow:hidden}aside{padding:14px 16px;overflow:auto;min-width:0;border-right:1px solid #2f4652}.design>aside:last-child{border-left:1px solid #2f4652;border-right:0}.design-canvas{background:#0c1720;padding:15px;overflow:auto;min-width:0}.design-canvas>svg{display:block;width:100%;max-height:580px;min-height:200px;background-image:linear-gradient(#344c551a 1px,transparent 1px),linear-gradient(90deg,#344c551a 1px,transparent 1px);background-size:20px 20px;overflow:visible}.selection{cursor:move;touch-action:none}label{display:grid;gap:5px;font-size:11px;color:#bed0d5;margin:9px 0}input,select,textarea{min-width:0;width:100%;box-sizing:border-box;padding:7px;border:1px solid #3a5360;border-radius:4px;background:#142731;color:#e0edf0;font:inherit}input[type=checkbox]{width:auto}input[type=color]{height:33px;padding:2px}textarea{min-height:75px;resize:vertical}.check{display:flex;align-items:center;gap:7px}.two{display:grid;grid-template-columns:1fr 1fr;gap:9px}.three{display:grid;grid-template-columns:1fr 1fr 30px;gap:7px;align-items:center}.property{display:flex;align-items:center;gap:5px}.property>label{flex:1}.property>button{margin-top:14px;padding:6px}.layers{padding:0;margin:0;list-style:none}.layers button{width:100%;justify-content:start;text-align:left;border-color:transparent;margin:2px 0;font-size:11px}.layers button>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.layers small{display:block;font-size:9px;color:#8ea8b1}h3{font-size:14px;margin:16px 0 9px}h3:first-child{margin-top:0}h3 small{font-size:10px;font-weight:400;color:#8aa4af}h4{font-size:12px;margin:10px 0 6px}p{line-height:1.6}.hint{font-size:11px;color:#8ea9b5;margin:8px 0 14px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px;max-width:1250px;margin:auto;padding:22px}.form-grid>section{min-width:0}article{padding:12px 14px;border:1px solid #304b58;border-radius:7px;margin:12px 0;background:#14252f}article>button,details>button{margin-right:6px;margin-top:7px;font-size:11px}details{border-top:1px solid #2c4551;margin:10px 0;padding:9px 0}summary{cursor:pointer;color:#b2d4d6;font-size:12px}.action-editor{margin:9px 0;padding:8px 10px;background:#10202b;border-left:2px solid #578e82}.action-editor>button{margin-top:7px;font-size:10px}.try-layout{display:grid;grid-template-columns:minmax(260px,1fr) 340px;gap:20px;padding:20px}.try-canvas{min-width:0}.try-canvas>div:first-child{max-height:540px;max-width:100%;margin:15px auto;background:#0b151e}.try-canvas>.actions{margin:12px 0}.try-layout aside{border:0;padding:0 8px}.empty{grid-column:1/-1;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:300px;text-align:center;color:#a2bec9}.empty p{max-width:430px}dl{font-size:11px;margin:10px 0}dl>div{display:flex;justify-content:space-between;gap:16px;padding:5px;border-bottom:1px solid #263d49}dt{color:#94b1bc;overflow-wrap:anywhere}dd{margin:0;overflow-wrap:anywhere;text-align:right}.error{padding:9px 20px;margin:0;background:#512b31;color:#ffccbd;font-size:12px}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #9adbc8;outline-offset:2px}@media(max-width:1000px){.workspace.design{grid-template-columns:170px minmax(220px,1fr) 250px}.buildbar{gap:6px}header{padding:12px}.try-layout{grid-template-columns:1fr 280px}}@media(max-width:750px){.generic-designer{overflow:auto}.workspace{height:auto;overflow:visible}.workspace.design{grid-template-columns:150px 1fr;overflow:visible}.design>aside:last-child{grid-column:1/-1}.form-grid,.try-layout{grid-template-columns:1fr;padding:14px}.buildbar{padding:8px}nav{overflow:auto;padding:7px}.title{font-size:18px}header p{display:none}header .actions{flex-wrap:wrap;justify-content:end}}
</style>
